package com.example.rokidgeminisecretary;
import android.app.*;import android.widget.*;import org.json.*;
final class AssistantReviewDialog {
 static void show(MainActivity owner){new Thread(()->{try{JSONObject data=AssistantReview.read(owner);owner.runOnUiThread(()->render(owner,data));}catch(Exception e){owner.runOnUiThread(()->Toast.makeText(owner,"記録を取得できません。保存内容は保持しています",Toast.LENGTH_LONG).show());}},"AssistantReview").start();}
 static void text(MainActivity o,LinearLayout box,String value){TextView t=new TextView(o);t.setText(value);t.setTextIsSelectable(true);box.addView(t);}
 static void button(MainActivity o,LinearLayout box,String title,Runnable action){Button b=new Button(o);b.setText(title);b.setOnClickListener(v->action.run());box.addView(b);}
 static void render(MainActivity o,JSONObject data){if(o.isDestroyed())return;LinearLayout box=new LinearLayout(o);box.setOrientation(1);box.setPadding(20,12,20,12);
 text(o,box,data.optString("diagnosis"));button(o,box,"直近の入力を訂正",()->o.beginRecentCorrection());button(o,box,"接続・未転送・処理状態",()->OperationOverviewDialog.show(o));button(o,box,"参照設定を確認",()->new ConversationWorkspaceDialog(o).show());button(o,box,"出発前の電池・空き容量",()->DepartureDialog.show(o));
 button(o,box,"簡易メモを保存",()->edit(o,"memo",""));button(o,box,"会話の続きカードを作る",()->edit(o,"continuation",data.optString("continuationDraft")));
 text(o,box,"メモはこの端末に暗号化保存。音声入力はキーボードの入力機能を明示操作してください。続きカードは話題・決定事項・未解決を自分で確認して記入します。");
 JSONArray notes=data.optJSONArray("notes");for(int i=notes.length()-1;i>=0;i--){JSONObject row=notes.optJSONObject(i);String id=row.optString("id"),value=row.optString("text");text(o,box,(row.optString("kind").equals("continuation")?"会話の続き":"メモ")+" / "+new java.util.Date(row.optLong("at"))+"\n"+value);
 button(o,box,"この内容を会話入力へ",()->o.composeLocalReview(value));button(o,box,"保留案件として保存",()->new AlertDialog.Builder(o).setMessage("このメモを保留案件として保存します。予定は登録しません。").setPositiveButton("保存",(d,w)->work(o,()->PersonalNotes.defer(o,id))).setNegativeButton("戻る",null).show());button(o,box,"このメモを削除",()->new AlertDialog.Builder(o).setMessage("このメモを削除しますか？").setPositiveButton("削除",(d,w)->work(o,()->PersonalNotes.delete(o,id))).setNegativeButton("戻る",null).show());}
 text(o,box,"保留案件の整理（30日以上・同名候補を表示。自動変更しません）");JSONArray rows=data.optJSONArray("inboxReview");for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);button(o,box,row.optString("title")+(row.optBoolean("old")?"・30日以上":"")+(row.optJSONArray("similar").length()>0?"・同名候補あり":""),()->new SecretaryInboxDialog(o).open(row.optString("id")));}
 ScrollView scroll=new ScrollView(o);scroll.addView(box);new AlertDialog.Builder(o).setTitle("ロキの状態・回答診断・メモ").setView(scroll).setPositiveButton("閉じる",null).setNeutralButton("再読込",(d,w)->show(o)).show();}
 interface Work{void run()throws Exception;}
 static void work(MainActivity o,Work action){new Thread(()->{String result;try{action.run();result="保存しました。表示を開き直して確認してください";}catch(Exception e){result=e.getMessage();}final String message=result;o.runOnUiThread(()->Toast.makeText(o,message,Toast.LENGTH_LONG).show());},"LocalReviewSave").start();}
 static void edit(MainActivity o,String kind,String initial){EditText input=new EditText(o);input.setMinLines(4);input.setText(initial);input.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(2400)});input.setHint(kind.equals("continuation")?"話題：\n決定したこと：\n未解決・次に話すこと：":"短いメモ");String id=java.util.UUID.randomUUID().toString();AlertDialog dialog=new AlertDialog.Builder(o).setTitle(kind.equals("memo")?"簡易メモ":"会話の続きカード").setView(input).setPositiveButton("保存",null).setNegativeButton("戻る",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(b->{String value=input.getText().toString();if(value.trim().isEmpty()){input.setError("内容を入力してください");return;}dialog.getButton(-1).setEnabled(false);new Thread(()->{try{PersonalNotes.save(o,new JSONObject().put("id",id).put("kind",kind).put("text",value));o.runOnUiThread(()->{dialog.dismiss();show(o);});}catch(Exception e){o.runOnUiThread(()->{dialog.getButton(-1).setEnabled(true);input.setError(e.getMessage());});}},"SavePersonalNote").start();}));dialog.show();}
 private AssistantReviewDialog(){}
}
